<?php require_once __DIR__.'/includes/functions.php';require_role(['admin']);$rows=$db->query('SELECT l.*,u.name,u.email FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 500');$title='Activity logs';require 'includes/header.php';?><h1>Activity logs</h1><div class="panel table-wrap"><p>Latest 500 events, including account changes, transaction workflow and login/logout.</p><table><tr><th>Date/time</th><th>User</th><th>Action</th><th>Record</th><th>Details</th><th>IP</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name']??'Deleted user')?><br><?=e($r['email']??'')?></td><td><?=e($r['action'])?></td><td><?=e($r['entity']??'')?> #<?=e($r['entity_id']??'')?></td><td><?=e($r['details'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endwhile;?></table></div><?php require 'includes/footer.php';?>
